class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        pu, pv = self.find(u), self.find(v)
        if pu == pv:
            return False
        self.parent[pu] = pv
        return True

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    robots = []
    for i in range(1, 2 * n, 2):
        x = int(data[i])
        d = int(data[i + 1])
        robots.append((x, x + d))

    robots.sort()

    uf = UnionFind(n)
    for i in range(n):
        x1, x2 = robots[i]
        for j in range(i + 1, n):
            y1, y2 = robots[j]
            if x2 >= y1:
                uf.union(i, j)
            else:
                break

    groups = set()
    for i in range(n):
        groups.add(uf.find(i))

    return len(groups)

if __name__ == "__main__":
    result = solve()
    print(result)
